// 1. Procesar los datos de InfluxDB
let datos = msg.payload;

// Verificar si hay datos
if (!Array.isArray(datos) || datos.length === 0) {
    msg.payload = {
        error: "No hay datos para procesar."
    };
    return msg;
}

// Obtener los nombres de las columnas (claves del primer objeto)
let columnas = Object.keys(datos[0]);

// Resumir los datos para crear un prompt más manejable
let resumen = datos.slice(0, 100).map(item => {
    let fila = {};
    columnas.forEach(columna => {
        fila[columna] = item[columna]; // Incluir todas las columnas y sus valores
    });
    return fila;
});

// Crear un prompt personalizado
let prompt = `Analiza los siguientes datos: ${JSON.stringify(resumen)}. ¿Qué conclusiones puedes sacar? ¿Hay algún dato que parezca incorrecto o fuera de lo esperado? Responder todo en español.`;

// 2. Estructurar el mensaje para Ollama
msg.payload = {
    "model": "Industrial", // Especifica el modelo de Ollama
    "messages": [
        {
            "role": "user", // Rol del mensaje (usuario)
            "content": prompt // El prompt creado con los datos procesados
        }
    ]
};

// Retornar el mensaje con la estructura correcta
return msg;

// Extraer el contenido de la respuesta de Ollama
var ollamaContent = msg.payload.message.content;

// Construir el objeto msg.payload para Telegram
msg.payload = {
    "chatId": 1144956543, // Reemplaza con el chatId correcto
    "type": "message",
    "content": ollamaContent // Usar el contenido de la respuesta de Ollama
};

